import{_ as l,r as t,o as i,c as u,e,a,s as p,d as s}from"./chunks/framework.CXcwiNg-.js";const q=JSON.parse('{"title":"Введение - October CMS - 3.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Ссылки на медиа","slug":"ссылки-на-медиа","link":"#ссылки-на-медиа","children":[]},{"level":2,"title":"Параметры конфигурации","slug":"параметры-конфигурации","link":"#параметры-конфигурации","children":[]},{"level":2,"title":"Аудио- и видеоплееры","slug":"аудио-и-видеоплееры","link":"#аудио-и-видеоплееры","children":[]},{"level":2,"title":"События","slug":"события","link":"#события","children":[]}],"relativePath":"3.x/ru/cms/media/introduction.md","filePath":"3.x/ru/cms/media/introduction.md"}'),r={name:"3.x/ru/cms/media/introduction.md"};function d(k,n,g,m,h,v){const o=t("pre-heading"),c=t("post-heading");return i(),u("div",null,[e(o),n[0]||(n[0]=a("h1",null,"Введение",-1)),e(c),n[1]||(n[1]=p(`<p>October CMS поставляется со встроенным менеджером медиа, что упрощает публикацию крупных ресурсов, таких как видео и фотографии. Эти ресурсы затем можно вставлять на страницы и в файлы контента через пользовательский интерфейс.</p><p><img src="https://github.com/octobercms/docs/blob/develop/images/media-manager.png?raw=true" alt="image"></p><h2 id="ссылки-на-медиа"><a href="#ссылки-на-медиа" class="header-anchor">#</a> Ссылки на медиа</h2><p>В большинстве случаев при вставке медиа-ресурсов в контент используется полный URL. Однако также можно генерировать эти URL из их относительных путей в директории медиа с помощью <a href="./../../markup/filter/media.html">Twig-фильтра</a> <code>|media</code>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> <span class="token string"><span class="token punctuation">&#39;</span>relative/path/to/asset.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>media <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block tip"><p>Обратитесь к <a href="./../../markup/filter/media.html">статье о фильтре Media</a>, чтобы узнать больше.</p></div><h2 id="параметры-конфигурации"><a href="#параметры-конфигурации" class="header-anchor">#</a> Параметры конфигурации</h2><p>Существует несколько параметров для тонкой настройки менеджера медиа, определённых в файле <strong>config/media.php</strong>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">/*
|--------------------------------------------------------------------------
| Ignored Files and Patterns
|--------------------------------------------------------------------------
|
| The media manager wil ignore file names and patterns specified here
|
*/</span>

<span class="token string single-quoted-string">&#39;ignore_files&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;.svn&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;.git&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;.DS_Store&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;.AppleDouble&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>

<span class="token string single-quoted-string">&#39;ignore_patterns&#39;</span> <span class="token operator">=&gt;</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;^\\..*&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span>
</code></pre></div><p>Конфигурация, определяющая место хранения медиа-файлов, находится в файле системной конфигурации. Обратитесь к <a href="./providers.html">статье о провайдерах</a> для использования сторонних провайдеров, таких как Amazon S3.</p><h2 id="аудио-и-видеоплееры"><a href="#аудио-и-видеоплееры" class="header-anchor">#</a> Аудио- и видеоплееры</h2><p>По умолчанию система использует HTML5-теги audio и video для воспроизведения аудио- и видеофайлов:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>video</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>video.mp4<span class="token punctuation">&quot;</span></span> <span class="token attr-name">controls</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>video</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>или</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>audio</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>audio.mp3<span class="token punctuation">&quot;</span></span> <span class="token attr-name">controls</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>audio</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Это поведение можно переопределить. Если существуют CMS-фрагменты <strong>oc-audio-player.htm</strong> и <strong>oc-video-player.htm</strong>, они будут использоваться для отображения аудио- и видеоконтента. Внутри фрагментов используйте переменную <strong>src</strong> для вывода ссылки на исходный файл. Пример:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>video</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{{ src }}<span class="token punctuation">&quot;</span></span> <span class="token attr-name">width</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>320<span class="token punctuation">&quot;</span></span> <span class="token attr-name">height</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>200<span class="token punctuation">&quot;</span></span> <span class="token attr-name">controls</span> <span class="token attr-name">preload</span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>video</span><span class="token punctuation">&gt;</span></span>
</code></pre></div>`,17)),n[2]||(n[2]=a("p",null,[s("Если вы не хотите использовать HTML5-плеер, вы можете предоставить любую другую разметку в фрагментах. Существует "),a("a",{href:"https://html5media.info/",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[s("сторонний скрипт"),a("span",null,[a("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[a("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),s(),a("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),s(),a("span",{class:"sr-only"},"(opens new window)")])]),s(", обеспечивающий поддержку HTML5-тегов video и audio в старых браузерах.")],-1)),n[3]||(n[3]=p(`<p>Поскольку фрагменты написаны на Twig, вы можете автоматизировать добавление альтернативных видеоисточников на основе соглашения об именовании. Например, если существует соглашение о наличии видео в меньшем разрешении для каждого видео в полном разрешении, и файл меньшего разрешения имеет расширение &quot;iphone.mp4&quot;, сгенерированная разметка может выглядеть так:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>video</span> <span class="token attr-name">controls</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>source</span>
        <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> src <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">media</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>only screen and (min-device-width: 568px)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>source</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>source</span>
        <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> src<span class="token operator">|</span>replace<span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string"><span class="token punctuation">&#39;</span>.mp4<span class="token punctuation">&#39;</span></span><span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>.iphone.mp4<span class="token punctuation">&#39;</span></span><span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span>
        <span class="token attr-name">media</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>only screen and (max-device-width: 568px)<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>source</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>video</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="события"><a href="#события" class="header-anchor">#</a> События</h2><p>Менеджер медиа предоставляет <a href="./../../extend/extending.html">несколько событий</a>, которые можно прослушивать для улучшения расширяемости.</p><div class="table"><table tabindex="0"><thead><tr><th>Событие</th><th>Описание</th><th>Параметры</th></tr></thead><tbody><tr><td><strong>folder.delete</strong></td><td>Вызывается при удалении папки</td><td><code>(string) $path</code></td></tr><tr><td><strong>file.delete</strong></td><td>Вызывается при удалении файла</td><td><code>(string) $path</code></td></tr><tr><td><strong>folder.rename</strong></td><td>Вызывается при переименовании папки</td><td><code>(string) $originalPath</code>, <code>(string) $newPath</code></td></tr><tr><td><strong>file.rename</strong></td><td>Вызывается при переименовании файла</td><td><code>(string) $originalPath</code>, <code>(string) $newPath</code></td></tr><tr><td><strong>folder.create</strong></td><td>Вызывается при создании папки</td><td><code>(string) $newFolderPath</code></td></tr><tr><td><strong>folder.move</strong></td><td>Вызывается при перемещении папки</td><td><code>(string) $path</code>, <code>(string) $dest</code></td></tr><tr><td><strong>file.move</strong></td><td>Вызывается при перемещении файла</td><td><code>(string) $path</code>, <code>(string) $dest</code></td></tr><tr><td><strong>file.upload</strong></td><td>Вызывается при загрузке файла</td><td><code>(string) $filePath</code>, <code>(\\Symfony\\Component\\HttpFoundation\\File\\UploadedFile) $uploadedFile</code></td></tr></tbody></table></div><p>Для подключения к этим событиям расширьте класс <code>Media\\Widgets\\MediaManager</code> напрямую.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name class-name-fully-qualified static-context">Media<span class="token punctuation">\\</span>Widgets<span class="token punctuation">\\</span>MediaManager</span><span class="token operator">::</span><span class="token function">extend</span><span class="token punctuation">(</span><span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$widget</span><span class="token operator">-&gt;</span><span class="token function">bindEvent</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;file.rename&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$originalPath</span><span class="token punctuation">,</span> <span class="token variable">$newPath</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token comment">// Update custom references to path here</span>
    <span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Или слушайте глобально через фасад <code>Event</code> (каждое событие имеет префикс <code>media.</code>, и первым параметром передаётся экземпляр объекта <code>Media\\Widgets\\MediaManager</code>).</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Event</span><span class="token operator">::</span><span class="token function">listen</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;media.file.rename&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$widget</span><span class="token punctuation">,</span> <span class="token variable">$originalPath</span><span class="token punctuation">,</span> <span class="token variable">$newPath</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// Update custom references to path here</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div>`,9))])}const w=l(r,[["render",d]]);export{q as __pageData,w as default};
